package app.yoru.anime;
import android.app.*;
import android.os.Bundle;
import android.content.Intent;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public final class DetailActivity extends Activity {
 Anime anime;List<Episode>videos=new ArrayList<>();String voice="",player="",number="1";Episode selected;Library library;
 TextView status,description;Button voiceButton,playerButton,seriesButton,watch,favorite,retry;boolean expanded=false;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);library=new Library(this);try{anime=new Anime(new JSONObject(getIntent().getStringExtra("anime")));}catch(Exception e){finish();return;}
  if(saved!=null){voice=saved.getString("voice","");player=saved.getString("player","");number=saved.getString("number","1");}
  LinearLayout window=Ui.root(this),root=Ui.column(this),header=Ui.padded(this,18);ScrollView fullScroll=new ScrollView(this);fullScroll.setFillViewport(true);fullScroll.addView(root);window.addView(fullScroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout top=Ui.row(this);Button back=Ui.button(this,"←",false);back.setContentDescription("Назад в каталог");back.setOnClickListener(v->finish());top.addView(back);TextView title=Ui.title(this,anime.title,21);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.leftMargin=Ui.dp(this,12);top.addView(title,tp);header.addView(top);Ui.add(header,Ui.text(this,anime.score()+"  ·  "+anime.meta(),12,Ui.MUTED),12);root.addView(header);
  LinearLayout selectors=Ui.padded(this,18);selectors.setBackground(Ui.shape(this,Ui.PANEL,14));TextView panelTitle=Ui.title(this,"Выбери, как смотреть",18);selectors.addView(panelTitle);status=Ui.text(this,"Загружаем серии…",12,Ui.MUTED);Ui.add(selectors,status,7);
  voiceButton=Ui.button(this,"Озвучка…",false);playerButton=Ui.button(this,"Плеер…",false);seriesButton=Ui.button(this,"Серия…",false);voiceButton.setEnabled(false);playerButton.setEnabled(false);seriesButton.setEnabled(false);
  Ui.add(selectors,voiceButton,14);LinearLayout row=Ui.row(this);row.addView(playerButton,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,-2,1);sp.leftMargin=Ui.dp(this,10);row.addView(seriesButton,sp);Ui.add(selectors,row,10);
  watch=Ui.button(this,"▶  Смотреть",true);watch.setEnabled(false);Ui.add(selectors,watch,14);watch.setOnClickListener(v->{if(selected!=null)startActivity(new Intent(this,PlayerActivity.class).putExtra("anime_id",anime.id).putExtra("video_id",selected.id));});
  retry=Ui.button(this,"Повторить загрузку",false);retry.setVisibility(View.GONE);Ui.add(selectors,retry,10);retry.setOnClickListener(v->load());
  LinearLayout.LayoutParams selp=new LinearLayout.LayoutParams(-1,-2);selp.setMargins(Ui.dp(this,18),0,Ui.dp(this,18),Ui.dp(this,12));root.addView(selectors,selp);
  LinearLayout info=Ui.padded(this,18);Ui.add(info,Ui.title(this,"О чём эта история",18),0);description=Ui.text(this,anime.description.isEmpty()?"Описание пока не добавлено.":anime.description,14,Ui.MUTED);description.setMaxLines(4);description.setEllipsize(android.text.TextUtils.TruncateAt.END);Ui.add(info,description,12);Button expand=Ui.button(this,"Развернуть описание ↓",false);Ui.add(info,expand,10);expand.setOnClickListener(v->{expanded=!expanded;description.setMaxLines(expanded?Integer.MAX_VALUE:4);expand.setText(expanded?"Свернуть описание ↑":"Развернуть описание ↓");});favorite=Ui.button(this,library.favorite(anime.id)?"♥  В избранном":"♡  В избранное",false);Ui.add(info,favorite,18);favorite.setOnClickListener(v->favorite.setText(library.toggle(anime)?"♥  В избранном":"♡  В избранное"));Button site=Ui.button(this,"Открыть на сайте ↗",false);Ui.add(info,site,10);site.setOnClickListener(v->Ui.site(this,anime));root.addView(info,new LinearLayout.LayoutParams(-1,-2));
  voiceButton.setOnClickListener(v->Ui.choose(this,"Озвучка",Sources.voices(videos),voice,s->{voice=s;List<String>p=Sources.players(videos,voice);if(!p.contains(player))player=p.isEmpty()?"":p.get(0);update();}));
  playerButton.setOnClickListener(v->Ui.choose(this,"Плеер",Sources.players(videos,voice),player,s->{player=s;update();}));seriesButton.setOnClickListener(v->{List<Episode>list=Sources.episodes(videos,voice,player);List<String>labels=new ArrayList<>();for(Episode e:list)labels.add(e.label());Ui.choose(this,"Серия",labels,"Серия "+number,s->{number=list.get(labels.indexOf(s)).number;update();});});load();
 }
 @Override protected void onSaveInstanceState(Bundle b){b.putString("voice",voice);b.putString("player",player);b.putString("number",number);super.onSaveInstanceState(b);}
 @Override protected void onResume(){super.onResume();if(library!=null&&!videos.isEmpty()){JSONObject last=library.last(anime.id);if(last!=null){voice=last.optString("voice",voice);player=last.optString("player",player);number=last.optString("number",number);update();}}}
 void load(){status.setText("Загружаем серии и озвучки…");retry.setVisibility(View.GONE);Api.IO.execute(()->{try{JSONObject raw=Api.get("anime/"+anime.id+"?need_videos=true").getJSONObject("response");Api.save(this,raw);List<Episode>result=Api.videos(raw);Anime fresh=new Anime(raw);runOnUiThread(()->{if(isDestroyed())return;anime=fresh;videos=result;description.setText(anime.description);if(videos.isEmpty()){status.setText("API не вернул доступных видео. Попробуй открыть аниме на сайте.");return;}JSONObject last=library.last(anime.id);if(voice.isEmpty()&&last!=null){voice=last.optString("voice");player=last.optString("player");number=last.optString("number","1");}List<String>vs=Sources.voices(videos);if(!vs.contains(voice))voice=vs.get(0);List<String>ps=Sources.players(videos,voice);if(!ps.contains(player))player=ps.get(0);List<Episode>eps=Sources.episodes(videos,voice,player);if(last==null&&Sources.match(videos,voice,player,number)==null&&!eps.isEmpty())number=eps.get(0).number;voiceButton.setEnabled(true);playerButton.setEnabled(true);seriesButton.setEnabled(true);update();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;status.setText(e instanceof java.io.IOException?e.getMessage():"Не удалось загрузить серии.");retry.setVisibility(View.VISIBLE);});}});}
 void update(){selected=Sources.match(videos,voice,player,number);voiceButton.setText(voice+" ⌄");playerButton.setText(player+" ⌄");seriesButton.setText(selected==null?"Выбери серию ⌄":selected.label()+" ⌄");watch.setEnabled(selected!=null);watch.setAlpha(selected==null?.5f:1f);status.setText(selected==null?"Серии "+number+" здесь нет. Выбери доступную серию.":"Можно начинать. Плеер откроется внутри приложения.");}
}
